{
  "identity": {
    "name": "North Star Kitchen and Bath Remodels",
    "location": "Boise, Idaho",
    "claims": [
      {
        "statement": "The business operates under the name North Star Kitchen and Bath Remodels.",
        "label": "fact",
        "sourceUrl": "https://northstarkitchenandbath.com/",
        "quote": "North Star Kitchen and Bath Remodels"
      },
      {
        "statement": "The company's office address is located on Main Street in Boise, Idaho.",
        "label": "fact",
        "sourceUrl": "https://northstarkitchenandbath.com/",
        "quote": "999 W Main St Suite 100, Boise, ID 83702"
      },
      {
        "statement": "The business describes itself as a family-owned remodeling company.",
        "label": "fact",
        "sourceUrl": "https://northstarkitchenandbath.com/",
        "quote": "As a family-owned business, we treat clients like family, providing personalized renovations that cater to every budget and always exceed expectations."
      }
    ]
  },
  "industry": {
    "industry": "Residential Kitchen and Bathroom Remodeling / General Contracting",
    "activities": [
      "Full-scale kitchen remodeling and renovations",
      "Bathroom remodeling and renovations",
      "Kitchen and bath design services",
      "Cabinetry supply and installation",
      "Countertop installation",
      "Flooring installation",
      "Bathtub refinishing and shower conversions"
    ],
    "claims": [
      {
        "statement": "The company provides full-scale kitchen renovations, kitchen design, cabinetry, countertops, flooring, islands, and open-concept remodeling in Boise.",
        "label": "fact",
        "sourceUrl": "https://northstarkitchenandbath.com/kitchen-remodel-cost-boise/",
        "quote": "North Star Kitchen and Bath Remodels offers full-scale renovations, kitchen design, cabinetry, countertops, flooring, islands, and open-concept remodels throughout Boise and the Treasure Valley."
      },
      {
        "statement": "The company operates as a residential remodeling contractor rather than a dedicated MEP (mechanical, electrical, plumbing) contractor.",
        "label": "inference",
        "sourceUrl": "https://northstarkitchenandbath.com/bathroom-renovation-cost/",
        "quote": null
      }
    ]
  },
  "publicInformation": {
    "officialWebsite": "https://northstarkitchenandbath.com/",
    "claims": [
      {
        "statement": "The business lists standard operating hours from 7:00 AM to 6:00 PM, Monday through Friday.",
        "label": "fact",
        "sourceUrl": "https://northstarkitchenandbath.com/",
        "quote": "Monday - Friday 7AM - 6PM"
      },
      {
        "statement": "The company advertises service coverage throughout the city of Boise and the surrounding Treasure Valley area.",
        "label": "fact",
        "sourceUrl": "https://northstarkitchenandbath.com/",
        "quote": "North Star Kitchen and Bath Remodels is proud to serve the city of Boise and the entire surrounding Treasure Valley area."
      }
    ]
  },
  "licensing": {
    "claims": [
      {
        "statement": "The company notes that specialized trade labor such as plumbing and electrical work is handled separately from standard remodeling tasks.",
        "label": "fact",
        "sourceUrl": "https://northstarkitchenandbath.com/bathroom-renovation-cost/",
        "quote": "Trade labor - from a licensed plumber, electrician, and tile installer - is priced separately and reflects both skill and liability."
      },
      {
        "statement": "The business describes its role as a general contractor managing subcontractors and project schedules to meet building codes.",
        "label": "fact",
        "sourceUrl": "https://northstarkitchenandbath.com/bathroom-renovation-cost/",
        "quote": "A general contractor typically charges 10 to 20 percent of the total project cost to manage subcontractors, coordinate scheduling, and ensure work meets building codes."
      }
    ],
    "limitations": "The website discusses trade permitting requirements and licensed subcontractors, but does not display a specific Idaho general contractor registration or state trade license number on the pages reviewed."
  },
