    {
      "statement": "The company actively solicits inbound estimate calls and online consultation requests.",
      "label": "fact",
      "sourceUrl": "https://northstarkitchenandbath.com/our-team-remodeling-contractors-boise/",
      "quote": "GET YOUR FREE ESTIMATE TODAY CALL US TODAY!"
    },
    {
      "statement": "Inbound online leads pass through a third-party msgsndr.com survey widget embedded directly into website pages.",
      "label": "inference",
      "sourceUrl": "https://northstarkitchenandbath.com/",
      "quote": null
