  ],
  "problems": [
    {
      "problem": "Mismatch with ForgeX's target market segment of HVAC, plumbing, and electrical service businesses.",
      "label": "fact",
      "basis": "The business is a kitchen and bathroom renovation design-build company and general contractor, not a dedicated mechanical, electrical, or plumbing service contractor."
    },
    {
      "problem": "Potential lead leakage or slow response times during off-hours or peak inquiry times.",
      "label": "hypothesis",
      "basis": "Inbound requests rely on phone calls and an embedded survey widget; off-hours triage and response speed cannot be observed from the outside."
    }
  ],
